<template>
  <div class="oripio-root" :class="{ 'is-transitioning': transitionLocked, 'is-returning': returning }">
    <LandingPage v-if="view === 'home'" @enter="beginEnter" />

    <div v-else class="app-shell">
      <div class="workspace-atmosphere" aria-hidden="true"><span></span><span></span><span></span></div>
      <aside class="app-sidebar">
        <button class="mini-brand" title="返回首页" aria-label="返回首页" @click="returnHome"><span>O</span><small>ORIPIO</small></button>
        <nav class="sidebar-nav" aria-label="主导航">
          <button v-for="item in menuItems" :key="item.key" class="nav-item" :class="{ active: currentPage === item.key }" :title="item.label" @click="navigateTo(item.key)">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path v-for="path in item.paths" :key="path" :d="path" /></svg><span>{{ item.label }}</span>
          </button>
        </nav>
        <div class="sidebar-bottom"><button class="nav-item" :class="{ active: currentPage === 'settings' }" title="系统设置" @click="navigateTo('settings')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2.8 2.8-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.6v.2h-4V21a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1L4.2 17l.1-.1a1.7 1.7 0 0 0 .3-1.9A1.7 1.7 0 0 0 3 14H2.8v-4H3a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9L4.2 7 7 4.2l.1.1A1.7 1.7 0 0 0 9 4.6 1.7 1.7 0 0 0 10 3V2.8h4V3a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.1-.1L19.8 7l-.1.1a1.7 1.7 0 0 0-.3 1.9 1.7 1.7 0 0 0 1.6 1h.2v4H21a1.7 1.7 0 0 0-1.6 1Z"/></svg><span>设置</span></button><div class="profile-chip"><span>R</span><div><strong>RuTika</strong><small>主账号 · 在线</small></div></div></div>
      </aside>

      <main class="app-main">
        <header class="app-header"><div class="header-title"><div class="breadcrumb"><span>ORIPIO</span><i>/</i>{{ pageTitle }}</div><h1>{{ pageTitle }}</h1><p>{{ pageSubtitle }}</p></div><div class="header-actions"><button class="command-trigger" @click="navigateTo('ask')"><span>⌘</span> 全局问析 <kbd>/</kbd></button><div class="live-status"><span></span> 服务正常</div><button class="header-icon" title="返回首页" @click="returnHome">⌂</button><button class="header-avatar">R</button></div></header>
        <div class="app-content"><Transition name="page" mode="out-in"><div :key="currentPage" class="page-stage"><OverviewPage v-if="currentPage === 'overview'" @navigate="navigateTo" @navigate-knowledge="navigateToKnowledge" /><AskPage v-else-if="currentPage === 'ask'" :initial-question="askQuestion" @question-consumed="askQuestion = ''" /><DataPage v-else-if="currentPage === 'data'" /><KnowledgePage v-else-if="currentPage === 'knowledge'" :initial-scene="knowledgeScene" @navigate-ask="navigateToAsk" /><SettingsPage v-else-if="currentPage === 'settings'" @database-switched="navigateTo('overview')" /></div></Transition></div>
      </main>
    </div>

    <PortalTransition :phase="phase" :target="targetPage" :reduced="reducedMotion" @midpoint="handleMidpoint" @complete="handleComplete" />
  </div>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import PortalTransition from './components/PortalTransition.vue'
import LandingPage from './pages/LandingPage.vue'
import OverviewPage from './pages/OverviewPage.vue'
import AskPage from './pages/AskPage.vue'
import DataPage from './pages/DataPage.vue'
import KnowledgePage from './pages/KnowledgePage.vue'
import SettingsPage from './pages/SettingsPage.vue'

type Page = 'overview' | 'ask' | 'data' | 'knowledge' | 'settings'
type Phase = 'home' | 'stream' | 'workspace'
const currentPage = ref<Page>('overview')
const targetPage = ref<Page>('overview')
const phase = ref<Phase>('home')
const view = ref<'home' | 'workspace'>('home')
const returning = ref(false)
const reducedMotion = ref(false)
const knowledgeScene = ref('production')
const askQuestion = ref('')
let phaseTimer = 0
const transitionLocked = computed(() => phase.value === 'stream' || returning.value)
const menuItems: { key: Page; label: string; paths: string[] }[] = [
  { key: 'overview', label: '总览', paths: ['M4 13h6V4H4v9Zm0 7h6v-4H4v4Zm10 0h6v-9h-6v9Zm0-16v4h6V4h-6Z'] },
  { key: 'ask', label: '智能问析', paths: ['M20 11.5a7 7 0 0 1-7 7H8l-4 3v-5.1a7 7 0 1 1 16-4.9Z', 'M8 11h.01M12 11h.01M16 11h.01'] },
  { key: 'data', label: '数据资源', paths: ['M4 6c0 1.1 3.6 2 8 2s8-.9 8-2-3.6-2-8-2-8 .9-8 2Z', 'M4 6v6c0 1.1 3.6 2 8 2s8-.9 8-2V6', 'M4 12v6c0 1.1 3.6 2 8 2s8-.9 8-2v-6'] },
  { key: 'knowledge', label: '业务知识', paths: ['M4 5.5A2.5 2.5 0 0 1 6.5 3H20v15H6.5A2.5 2.5 0 0 0 4 20.5v-15Z', 'M4 20.5A2.5 2.5 0 0 1 6.5 18H20'] },
]
const copy: Record<Page, [string, string]> = { overview: ['总览', '让数据关系、语义向量和业务信号在同一个空间里被看见'], ask: ['智能问析', '用自然语言向你的数据库提问'], data: ['数据资源', '管理数据源、表结构和字段语义'], knowledge: ['业务知识', '整理业务对象、指标与规则'], settings: ['系统设置', '配置模型和数据库连接'] }
const pageTitle = computed(() => copy[currentPage.value][0])
const pageSubtitle = computed(() => copy[currentPage.value][1])
function normalizePage(page: string): Page { return ['overview','ask','data','knowledge','settings'].includes(page) ? page as Page : 'overview' }
function beginEnter(page: string) { if (transitionLocked.value || view.value !== 'home') return; targetPage.value = normalizePage(page); phase.value = 'stream' }
function handleMidpoint() { if (phase.value !== 'stream') return; currentPage.value = targetPage.value; view.value = 'workspace' }
function handleComplete() { if (phase.value === 'stream') phase.value = 'workspace' }
function returnHome() { if (transitionLocked.value || view.value === 'home') return; returning.value = true; window.clearTimeout(phaseTimer); phaseTimer = window.setTimeout(() => { view.value = 'home'; phase.value = 'home'; returning.value = false }, reducedMotion.value ? 180 : 320) }
function navigateTo(page: string) { if (!transitionLocked.value) currentPage.value = normalizePage(page) }
function navigateToKnowledge(sceneKey: string) { knowledgeScene.value = sceneKey; navigateTo('knowledge') }
function navigateToAsk(question: string) { askQuestion.value = question; navigateTo('ask') }
function handleShortcut(event: KeyboardEvent) { if (event.key === '/' && !event.metaKey && !event.ctrlKey && view.value === 'workspace' && !['INPUT','TEXTAREA','SELECT'].includes((event.target as HTMLElement).tagName)) { event.preventDefault(); navigateTo('ask') } }
onMounted(() => { reducedMotion.value = window.matchMedia('(prefers-reduced-motion: reduce)').matches; window.addEventListener('keydown', handleShortcut) })
onBeforeUnmount(() => { window.clearTimeout(phaseTimer); window.removeEventListener('keydown', handleShortcut) })
</script>

