mand-trigger span { color:#70dece; }.command-trigger kbd { margin-left:7px;padding:1px 5px;border:1px solid rgba(255,255,255,.1);border-radius:4px;color:#536674;font-family:inherit; }.live-status { display:flex;align-items:center;gap:6px;padding:8px 10px;border-radius:20px;color:#66b8a9;background:rgba(39,172,148,.08);font-size:9px; }.live-status span { width:5px;height:5px;border-radius:50%;background:#3ad1aa;box-shadow:0 0 9px #3ad1aa; }.header-icon { width:31px;height:31px;border:1px solid rgba(161,194,216,.13);border-radius:9px;color:#738696;background:rgba(255,255,255,.03);cursor:pointer; }.header-avatar { border:0; }.app-content { padding:28px 38px 52px; }.page-stage { width:100%; }.page-enter-active,.page-leave-active { transition:opacity .24s ease,transform .28s cubic-bezier(.2,.8,.2,1),filter .24s; }.page-enter-from { opacity:0;transform:translateY(9px) scale(.995);filter:blur(4px); }.page-leave-to { opacity:0;transform:translateY(-5px) scale(.998);filter:blur(2px); }.is-returning .app-shell { opacity:0;transform:scale(1.015);filter:blur(8px);transition:opacity .3s,transform .32s,filter .3s; }
